import csv
from collections import defaultdict
rows=list(csv.DictReader(open(VALUES_CSV)))
catalog=list(csv.DictReader(open(CATALOG_CSV)))
cmap={c['point_uri'].split('#')[-1]: c['timeseries_id'] for c in catalog}
ids={
'F3_Sensor':'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
'F3_CoolSP':'5b98cbc1-fd25-5d8c-a96e-c3de49819174',
'F3_HeatSP':'b7f22e0c-833d-5373-87e1-51e1cb26f038',
}
data=defaultdict(dict)
for r in rows:
    if r['timeseries_id'] in ids.values():
        data[r['timeseries_id']][r['timestamp']]=float(r['value'])
# sample around month boundaries
ts=sorted(set(r['timestamp'] for r in rows))
import json
# Print monthly means
def monthly(id):
    vals=defaultdict(list)
    for t,v in data[id].items():
        vals[t[:7]].append(v)
    return {m:round(sum(v)/len(v),2) for m,v in sorted(vals.items())}
print('F3 sensor', monthly(ids['F3_Sensor']))
print('F3 Cool SP', monthly(ids['F3_CoolSP']))
print('F3 Heat SP', monthly(ids['F3_HeatSP']))
# compare with other zones sensor
cmap2={c['point_uri'].split('#')[-1]: c['timeseries_id'] for c in catalog}
for z in ['Zone_F2_Z01','Zone_F4_Z01','Zone_F3_Z03','Zone_F3_Z02','Zone_F3_Z05']:
    k=z+'.Zone_Air_Temperature_Sensor'
    id=cmap2[k]
    dd=defaultdict(list)
    for t,v in data[id].items():
        dd[t[:7]].append(v)
    print(z, {m:round(sum(v)/len(v),2) for m,v in sorted(dd.items())})
